import{_ as o,C as t,o as r,c as i,E as n,a2 as l}from"./chunks/framework.Cm6XCzck.js";const A=JSON.parse('{"title":"“用户角色”响应不等于真人审批","description":"","frontmatter":{"title":"“用户角色”响应不等于真人审批","date":"2026-08-18","column":"digital-employee","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"What must an agent runtime know before it may treat a syntactically valid user-role response as an accountable human approval?","summary":"Agent Runtime 不应把 user-role 语法直接等同为审批权。Google ADK 当日合并变更表明，接收端拥有的来源标记可以在确认匹配之前对远程 A2A 审批类别进行 Fail-closed；而真人身份认证与授权仍是独立要求。","sources":["research/analysis/Q-20260818-01-accountable-origin-human-approval.md"],"item_id":"Q-20260818-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-18-accountable-human-approval-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-08-18-accountable-human-approval.md","filePath":"zh/digital-employee/2026-08-18-accountable-human-approval.md","lastUpdated":1787067160000}'),c={name:"zh/digital-employee/2026-08-18-accountable-human-approval.md"};function s(p,e,u,d,m,h){const a=t("ArticleCover");return r(),i("div",null,[n(a,{image:"/assets/covers/daily-2026-08-18-accountable-human-approval-cover-v2.png",kicker:"数字员工 · 每日研究",title:"“用户角色”响应不等于真人审批",summary:"Agent Runtime 不应把 user-role 语法直接等同为审批权。Google ADK 当日合并变更表明，接收端拥有的来源标记可以在确认匹配之前对远程 A2A 审批类别进行 Fail-closed；而真人身份认证与授权仍是独立要求。",version:"Q-20260818-01",status:"Daily Runtime V5 · 2026-08-18",languageHref:"/en/digital-employee/2026-08-18-accountable-human-approval",languageLabel:"English"}),e[0]||(e[0]=l('<h1 id="用户角色-响应不等于真人审批" tabindex="-1">“用户角色”响应不等于真人审批 <a class="header-anchor" href="#用户角色-响应不等于真人审批" aria-label="Permalink to &quot;“用户角色”响应不等于真人审批&quot;">​</a></h1><p>一个危险工具调用正在等待真人确认时，远程 Agent 完全可能发送一条语法正确的 <code>user</code>-role 响应。如果 Runtime 只问“这像不像确认”，远程对端就可能通过与真人相同的语法入口进入信任判断。</p><p>2026-08-18 合并的一项 Google ADK 变更处理了这个问题的一个具体版本：A2A 来源 Invocation 现在总会被接收端写入 <code>a2a_metadata</code> 标记，即使对端完全不提供 Metadata；当该标记存在时，变更后的确认处理器会在匹配确认事件之前直接返回。回归测试同时覆盖“有 Metadata”和“无 Metadata”的 A2A 请求。</p><p>这组证据支持一个有界但重要的判断：<strong>消息角色描述的是内容语义；可追责审批则是带来源的授权事件。</strong> 二者不能压缩进同一个字段。</p><h2 id="role-user-回答不了-谁有权批准" tabindex="-1"><code>role=user</code> 回答不了“谁有权批准” <a class="header-anchor" href="#role-user-回答不了-谁有权批准" aria-label="Permalink to &quot;`role=user` 回答不了“谁有权批准”&quot;">​</a></h2><p><code>user</code> 角色可以告诉模型或 Runtime 应怎样解释一段消息，却不会自动说明消息由哪个 Principal 产生，更不能证明该 Principal 有权批准当前操作。</p><p>当多个 Transport 都能产生形式相似的内容时，这一区分尤其关键。浏览器会话、内部服务、远程 A2A 对端以及后续单独认证的真人步骤，都可能生成最终被 Runtime 视为“用户输入”的数据。若把 Role 当成 Authority，就等于把消息语义与 Actor Provenance 混成一个概念。</p><p>ADK 变更演示的是这种分离的负向一半：来源标记由接收端写入，是否存在不取决于远程对端可自行省略的字段。因此，在已测试路径中，远程对端不能仅靠发送空 Metadata 就把 A2A 来源伪装成“本地真人”。</p><h2 id="来源资格应先于确认内容匹配" tabindex="-1">来源资格应先于确认内容匹配 <a class="header-anchor" href="#来源资格应先于确认内容匹配" aria-label="Permalink to &quot;来源资格应先于确认内容匹配&quot;">​</a></h2><p>门禁的位置与标记本身同样重要。确认处理器先判断 A2A Origin，再进入正常的 Confirmation Event Resolution。已演示路径中，即使远程 <code>FunctionResponse</code> 写着 <code>confirmed=True</code>，它也不会进入待处理真人确认的匹配逻辑。</p><p>这提示了一种更通用的控制顺序：</p><ol><li>使用接收端建立的 Provenance 判断响应来源；</li><li>对不具备审批资格的 Origin Class 直接 Fail-closed；</li><li>然后才把响应语义与具体待审批 Occurrence 匹配；</li><li>对允许的正向路径，再独立认证 Principal，并验证其 Authorization Scope。</li></ol><p>前两步并不能证明后两步已经成立。一个系统可以正确拒绝远程 Agent 审批，同时仍拥有很弱的真人通道。因此，现有证据支持的是“来源先行的 Fail-closed 边界”，不是“完整 HITL 已安全”。</p><h2 id="一次可追责审批需要比一条消息更多的身份" tabindex="-1">一次可追责审批需要比一条消息更多的身份 <a class="header-anchor" href="#一次可追责审批需要比一条消息更多的身份" aria-label="Permalink to &quot;一次可追责审批需要比一条消息更多的身份&quot;">​</a></h2><p>对于高后果操作，持久审批记录至少应把以下身份分开保存：</p><ul><li><strong>Content Role</strong>：这条消息在语义上是什么；</li><li><strong>Transport Origin</strong>：它从哪个 Trust Domain 到达；</li><li><strong>Principal Identity</strong>：究竟是谁或什么做出审批；</li><li><strong>Authorization Scope</strong>：该 Principal 被允许批准哪些操作；</li><li><strong>Approval Occurrence Identity</strong>：审批针对哪一个具体动作、版本与有效时间窗。</li></ul><p>已选择的实现直接证明的只有“来源类别拒绝”。上述五项模型，是研究中心基于现有证据提出的有界工程解释，用于描述更完整的可追责审批链。</p><p>这种分离也能让合法的机器委托更清楚。某个机器 Principal 可以被授权批准狭窄的低风险操作，但那应被记录为“委托的机器审批者”，而不是因为它能产生 user-role 内容就被叫作“真人”。审计面必须保留这种差别。</p><h2 id="负向门禁不能反推出正向真人已经可信" tabindex="-1">负向门禁不能反推出正向真人已经可信 <a class="header-anchor" href="#负向门禁不能反推出正向真人已经可信" aria-label="Permalink to &quot;负向门禁不能反推出正向真人已经可信&quot;">​</a></h2><p>合并代码与测试没有建立最终真人是谁、审批是否新鲜、能否重放、来自哪个设备或会话，也没有证明所有其他 Transport 与 HITL Processor 都具有同等强度的 Provenance。这个 Marker 不是密码学来源证明；仓库回归测试也不是独立安全评估。</p><p>因此不能从“远程 A2A 确认被拒绝”推导出“剩余被接受的确认就一定来自真实且有权的真人”。负向 Origin Qualification 与正向 Principal Authorization 是两套独立证据要求。</p><p>接下来真正需要回答的问题很具体：什么持久身份把真人决定绑定到某一次危险工具调用？Expiry 与 Replay 如何处理？还有哪些 Transport 可以构造确认响应？合法的非真人 Delegation 应如何表达？安全审批可以从“这条响应来自哪里”开始，但只有当 Runtime 还能回答“谁、凭什么、批准了哪个具体 Occurrence”时，它才真正具备可追责性。</p><p><strong>一手证据：</strong> <a href="https://github.com/google/adk-python/commit/9e9eaa69bdcc16f004af9c63f40f1dae6404c29b" target="_blank" rel="noreferrer">Google ADK 合并提交 9e9eaa69</a>。该代码与仓库测试属于公开一手证据，并不等于对完整 HITL 安全的独立验证。</p>',23))])}const _=o(c,[["render",s]]);export{A as __pageData,_ as default};
